export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const MAX_INPUT_LENGTH = 1000;

function isIntegerIn(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

/** Validates a parsed request body and applies defaults. Collects every offending field. */
export function validateSubmission(body: unknown): ValidationResult {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const record = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(record)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'is not an allowed field' });
  }

  const input = record.input;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'is required and must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  }

  const steps = record.steps === undefined ? 5 : record.steps;
  if (!isIntegerIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });

  const failAttempts = record.failAttempts === undefined ? 0 : record.failAttempts;
  if (!isIntegerIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

