import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { JOB_COLUMNS, nowIso, openDatabase, toJob, transaction, type Job, type JobRow } from './db.ts';
import { validateSubmission, type FieldError, type Submission } from './validate.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 16 * 1024;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const selectById = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`);
const selectByKey = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE idempotency_key = ?`);
const selectAll = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`);
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?)`,
);
const selectWorkerHeartbeat = db.prepare(`SELECT at FROM heartbeat WHERE name = 'worker'`);

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

type SubmitOutcome = { status: 200 | 201; job: Job } | { status: 409 };

function submit(submission: Submission, key: string | null): SubmitOutcome {
  return transaction(db, () => {
    if (key !== null) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === submission.input &&
          existing.steps === submission.steps &&
          existing.fail_attempts === submission.failAttempts;
        return same ? { status: 200, job: toJob(existing) } : { status: 409 };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    insertJob.run(id, submission.input, submission.steps, submission.failAttempts, key, now, now);
    return { status: 201, job: toJob(selectById.get(id) as JobRow) };
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const raw = await readBody(req);
  const contentType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let submission: Submission | undefined;
  if (raw === undefined) {
    fields.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (contentType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    let parsed: unknown;
    let parseOk = true;
    try {
      parsed = JSON.parse(raw);
    } catch {
      parseOk = false;
      fields.push({ field: 'body', message: 'is not valid JSON' });
    }
    if (parseOk) {
      const result = validateSubmission(parsed);
      if (result.ok) submission = result.value;
      else fields.push(...result.fields);
    }
  }

  if (fields.length > 0 || submission === undefined) {
    return sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
  }

  const outcome = submit(submission, key ?? null);
  if (outcome.status === 409) {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.status, outcome.job);
}

function workerIsUp(): boolean {
  const row = selectWorkerHeartbeat.get() as { at: number } | undefined;
  return row !== undefined && Date.now() - Number(row.at) <= WORKER_FRESH_MS;
}

function route(req: IncomingMessage, res: ServerResponse): void | Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  const methodNotAllowed = (allow: string) =>
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`) ||
    res.setHeader('allow', allow);

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed('GET');
    return send(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const jobs = (selectAll.all() as unknown as JobRow[]).map(toJob);
      return send(res, 200, { jobs });
    }
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed('GET, POST');
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const row = selectById.get(id) as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => route(req, res))
    .catch((err: unknown) => {
      console.error('request failed:', err);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal error.');
    });
});

server.on('error', (err) => {
  console.error(`server failed to listen on ${port}: ${err.message}`);
  process.exit(1);
});

server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
process.on('SIGTERM', () => {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
});

