import { setTimeout as sleep } from 'node:timers/promises';
import { JOB_COLUMNS, nowIso, openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
/** Total attempts per job, including the first. */
const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. Must be between 250 and 2000 ms. */
const RETRY_DELAY_MS = 500;

const db = openDatabase();
let stopping = false;

const selectDue = db.prepare(
  `SELECT id FROM jobs WHERE status = 'queued' AND (next_run_at IS NULL OR next_run_at <= ?) ORDER BY seq ASC LIMIT 1`,
);
const claim = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, next_run_at = NULL, updated_at = ?
   WHERE id = ? AND status = 'queued'`,
);
const selectById = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`);
const setProgress = db.prepare(
  `UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const complete = db.prepare(
  `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const requeueWithDelay = db.prepare(
  `UPDATE jobs SET status = 'queued', progress_completed = 0, error = NULL, next_run_at = ?, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
const failPermanently = db.prepare(
  `UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = 'transient failure', updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
/** Returns an interrupted attempt to the queue without counting it, so it is processed again as the same attempt. */
const requeueInterrupted = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);
